import generatedWorker from "./.open-next/worker.js";
import { cleanupOAuthRecords } from "@/lib/db/oauth";
export { TelegramExpenses } from "@/worker/telegram-expenses";

export default {
	fetch: generatedWorker.fetch,
	async scheduled(_controller, env) {
		const result = await cleanupOAuthRecords(env.DB);
		if (result.err) {
			console.error(JSON.stringify({ event: "oauth_cleanup_failed" }));
			throw new Error("OAuth maintenance failed.");
		}
		console.info(JSON.stringify({ event: "oauth_cleanup", ...result.val }));
	},
} satisfies ExportedHandler<CloudflareEnv>;

